  ('lesson:smartciti-holodeck/module/boom-lift', 'smartciti-holodeck', 'Boom Lift Basket Work', 'worldforge/out/training/smartciti-holodeck.json', E'{"assessment":{"axes":[{"applies_to":["robot","person"],"axis":"reach","id":"source:reach","measure":"marked work points the basket was brought to, within tolerance, in order","pass":"== all","status":"measured","verdict":"pass"},{"applies_to":["robot","person"],"axis":"envelope","id":"source:envelope","measure":"load-moment envelope exceedances (outreach x platform load over the rated moment)","pass":"== 0","status":"measured","verdict":"pass"},{"applies_to":["person"],"axis":"tie-off","id":"source:tie-off","measure":"harness clipped before the basket left the ground","pass":"required","reason":"clipping the harness has no verb; a human check before the basket leaves the ground","status":"not measurable in simulation"},{"applies_to":["person"],"axis":"slope","id":"source:slope","measure":"stabilizers set on the level pad before the first lift","pass":"required","reason":"setting the stabilizers has no verb; a human check before the first lift","status":"not measurable in simulation"},{"applies_to":["robot","person"],"axis":"strikes","id":"source:strikes","measure":"basket entries into the overhead-line exclusion zone","pass":"== 0","status":"measured","verdict":"pass"},{"applies_to":["person"],"axis":"time","id":"source:time","measure":"seconds tie-off to stowed","pass":"informational","reason":"informational in the source; the simulator has no clock","status":"not measurable in simulation"},{"applies_to":["person"],"axis":"communication","id":"person:communication","reason":"crew communication is taught in the hall''s coordination room; the robot run has no crew","status":"not measurable in simulation"},{"applies_to":["person"],"axis":"judgement","id":"person:judgement","reason":"when to stop, refuse or ask is a person''s call, observed by the instructor; the robot''s equivalent is a mechanical limit check","status":"